def solution(board):
  height = len(board)
  width = len(board[0])
  for row in range(height):
    for col in range(width):
      if board[row][col] == 'S':
        start_row, start_col = row, col

  distance = [[[-1] * 4 for _ in range(width)] for _ in range(height)]
  distance[start_row][start_col][0] = 0
  queue = deque([(start_row, start_col, 0)])

  while queue:
    row, col, mask = queue.popleft()
    steps = distance[row][col][mask]
    if board[row][col] == 'E' and mask == 3:
      return steps

    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
      next_row, next_col = row + dr, col + dc
      if not (0 <= next_row < height and 0 <= next_col < width):
        continue
      cell = board[next_row][next_col]
      if cell == '#':
        continue
      next_mask = mask
      if cell == 'A':
        next_mask |= 1
      elif cell == 'B':
        next_mask |= 2
      if distance[next_row][next_col][next_mask] != -1:
        continue
      distance[next_row][next_col][next_mask] = steps + 1
      queue.append((next_row, next_col, next_mask))

  return -1

def solution(brightness, forbidden, target):
  count = len(brightness)
  banned = [[False] * count for _ in range(count)]
  for a, b in forbidden:
    banned[a][b] = True
    banned[b][a] = True

  visited = [False] * count
  path = []
  answer = []

  def dfs(score):
    if len(path) == count:
      if score == target:
        answer.append(path.copy())
      return

    position = len(path) + 1
    for card in range(count):
      if visited[card]:
        continue
      if path and banned[path[-1]][card]:
        continue
      next_score = score + position * brightness[card]
      if next_score > target:
        continue
      visited[card] = True
      path.append(card)
      dfs(next_score)
      path.pop()
      visited[card] = False

  dfs(0)
  return answer

